import Observation
struct Screening {
    let id = 21
    let seatPrice = 400
    func cost(seats: Int) -> Int { seats * seatPrice }
}
@Observable final class BookingViewModel {
    var seats = 1
    private let screening = Screening()
    var costText: String { "К оплате: \(screening.cost(seats: seats)) ₽" }
}
let viewModel = BookingViewModel()
viewModel.seats = 3
print(viewModel.costText)

import Observation
struct Photo {
    let id = 31
    func hasCaption(_ caption: String) -> Bool { !caption.isEmpty }
}
@Observable final class UploadViewModel {
    var caption = ""
    var message = "Добавь подпись"
    private let photo = Photo()
    func check() {
        if !caption.isEmpty { message = photo.hasCaption(caption) ? "Можно отправлять" : "Добавь подпись" }
    }
}
let viewModel = UploadViewModel()
viewModel.caption = "Море"
viewModel.check()
viewModel.caption = ""
viewModel.check()
print(viewModel.message)

