import Observation
struct FocusPlan {
    func seconds(minutes: Int) -> Int { minutes * 60 }
}
@Observable final class FocusViewModel {
    var minutes = 10
    private let plan = FocusPlan()
    var durationText: String { "Длительность: \(plan.seconds(minutes: minutes)) с" }
}
let viewModel = FocusViewModel()
viewModel.minutes = 15
print(viewModel.durationText)

FocusPlan переводит минуты в секунды, ViewModel создаёт подпись. При 15 минутах вывод «Длительность: 900 с».
